import Foundation

/// Copy for the merchant-ops parity surfaces lives in its own bilingual table (Resources/MerchantOps.xcstrings),
/// regenerated by tools/build_merchant_ops_catalog.py, so these pages never edit the shared catalog.
enum MerchantOpsCopy {
    static let table = "MerchantOps"
    static func text(_ key: String, _ arguments: CVarArg...) -> String {
        let format = Bundle.main.localizedString(forKey: key, value: nil, table: table)
        return arguments.isEmpty ? format : String(format: format, locale: Locale.current, arguments: arguments)
    }
}
